Running command: python3 - <<'PY'
import struct, math

def bits(x):
    return struct.unpack('<Q', struct.pack('<d', x))[0]
def fbits(b):
    return struct.unpack('<d', struct.pack('<Q', b & 0xFFFFFFFFFFFFFFFF))[0]

def simulate(beg, end, excl, hardcap=200):
    a = float(beg)
    b = end
    if a > b:
        return None
    cap = int(b - a) + 1
    i = 0
    if excl:
        while a < b:
            i += 1
            a += 1.0
            if i > hardcap:
                return (cap, i, "HANG")
    else:
        while a <= b:
            i += 1
            a += 1.0
            if i > hardcap:
                return (cap, i, "HANG")
    return (cap, i, "OK")

single = []
hangs = []
for exp in range(0, 56):
    base = 2**exp
    for beg in list(range(max(0,base-5), base+6)) + [base*2-2, base*2-1]:
        a0 = float(beg)
        for k in range(0, 8):
            center = a0 + k
            if center != center or math.isinf(center):
                continue
            for delta_bits in range(-8, 9):
                end = fbits(bits(center) + delta_bits)
                if end != end or math.isinf(end):
                    continue
                for excl in [False, True]:
                    r = simulate(beg, end, excl)
                    if not r: continue
                    cap, i, status = r
                    if status == "HANG":
                        hangs.append((beg, end, repr(end), excl, cap))
                    elif i == cap + 1:
                        single.append((beg, end, repr(end), excl, cap, i))

print("single off-by-one count:", len(single))
for f in single[:40]:
    print("SINGLE", f)
print()
print("hang count:", len(hangs))
for f in hangs[:20]:
    print("HANG", f)
PY

